            'x': d['throughput_million'],
            'y': d['on_time_rate'],
            'r': r,
            'airport': d['airport'],
            'routes': d['routes']
        })

    datasets.append({
        'label': region,
        'data': dataset_data,
        'backgroundColor': colors.get(region, 'rgba(100,100,100,0.7)'),
        'borderColor': border_colors.get(region, 'rgba(100,100,100,1)'),
        'borderWidth': 1
    })

